class TestCheckLowVariance:
    def test_normal_check(self, sample_df):
        result = AnalysisTools.check_low_variance(sample_df, threshold=0.85)
        assert "error" not in result
        assert "constant_col" in result["quasi_cols"]
        assert "quasi_constant" in result["quasi_cols"]
        # score has no dominant value exceeding 0.85 (max is 85.5 twice => 20%)
        assert "score" not in result["quasi_cols"]
        assert result["threshold"] == 0.85
        
    def test_no_low_variance(self, sample_df):
        result = AnalysisTools.check_low_variance(sample_df, threshold=1.1)
        assert len(result["quasi_cols"]) == 0
